/* FormFit service worker. Generated by app.py (route /sw.js); edit the
   template, not dist/sw.js.

   - Calculator pages, hubs, CSS, JS and fonts are precached on install, so
     every calculator works offline (all the maths runs in calc.js).
   - Pages: network first, falling back to the cached copy, then /offline.
   - /static/: cache first. Those URLs carry a ?v=<hash> or never change.
   - Other origins (AdSense) and non-GET requests are left alone. */
"use strict";

var VERSION = "382e343c1e";
var CORE = "formfit-core-" + VERSION;
var PAGES = "formfit-pages-" + VERSION;
var STATIC = "formfit-static";
var PRECACHE = ["/", "/calculators", "/offline", "/bmi-calculator", "/body-fat-calculator", "/ideal-weight-calculator", "/lean-body-mass-calculator", "/ffmi-calculator", "/waist-to-hip-ratio-calculator", "/tdee-calculator", "/calorie-calculator", "/macro-calculator", "/protein-calculator", "/bmr-calculator", "/weight-loss-calculator", "/water-intake-calculator", "/one-rep-max-calculator", "/plate-calculator", "/wilks-calculator", "/heart-rate-zone-calculator", "/calories-burned-calculator", "/static/css/style.css?v=ea708adbb6", "/static/js/site.js?v=fe3d285349", "/static/js/calc.js?v=c7a8f7252c", "/static/img/mark.svg?v=bf4caf9db6", "/static/img/favicon.ico?v=f278306083", "/static/fonts/archivo-latin-500-normal.woff2", "/static/fonts/archivo-latin-700-normal.woff2", "/static/fonts/archivo-latin-800-normal.woff2", "/static/fonts/ibm-plex-mono-latin-400-normal.woff2", "/static/fonts/ibm-plex-mono-latin-500-normal.woff2", "/static/fonts/ibm-plex-mono-latin-600-normal.woff2", "/static/fonts/ibm-plex-sans-latin-400-normal.woff2", "/static/fonts/ibm-plex-sans-latin-500-normal.woff2", "/static/fonts/ibm-plex-sans-latin-600-normal.woff2"];
var MAX_PAGES = 60;
var MAX_STATIC = 120;
var NETWORK_TIMEOUT = 4000;

// A redirected response can't be served for a navigation, so store a clean
// copy. (Some static servers redirect /page to /page/.)
function clean(res) {
  if (!res.redirected) return Promise.resolve(res);
  return res.blob().then(function (body) {
    return new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers });
  });
}

self.addEventListener("install", function (e) {
  e.waitUntil(caches.open(CORE).then(function (cache) {
    return Promise.all(PRECACHE.map(function (url) {
      return fetch(url, { cache: "reload" }).then(function (res) {
        if (!res.ok) throw new Error(url + " " + res.status);
        return clean(res).then(function (r) { return cache.put(url, r); });
      });
    }));
  }).then(function () { return self.skipWaiting(); }));
});

self.addEventListener("activate", function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) {
      return k.indexOf("formfit-") === 0 && k !== CORE && k !== PAGES && k !== STATIC;
    }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});

function trim(name, max) {
  return caches.open(name).then(function (cache) {
    return cache.keys().then(function (keys) {
      if (keys.length > max) return cache.delete(keys[0]).then(function () { return trim(name, max); });
    });
  });
}

// /page and /page/ are the same page: hosts redirect one to the other, and
// the browser remembers that redirect even offline.
function fromCache(req) {
  var url = req.url.split("?")[0];
  var alt = /\/$/.test(url) ? url.replace(/\/+$/, "") : url + "/";
  return caches.match(url).then(function (hit) {
    return hit || caches.match(alt);
  });
}

function page(e) {
  var req = e.request;
  var network = fetch(req).then(function (res) {
    if (res.ok && res.type === "basic") {
      var copy = res.clone();
      e.waitUntil(clean(copy).then(function (r) {
        return caches.open(PAGES).then(function (c) { return c.put(req.url.split("?")[0], r); });
      }).then(function () { return trim(PAGES, MAX_PAGES); }));
    }
    return res;
  });
  return new Promise(function (resolve) {
    var done = false;
    function finish(res) {
      if (res && !done) { done = true; resolve(res); }
    }
    network.then(finish, function () {
      fromCache(req).then(function (hit) {
        return hit || caches.match("/offline");
      }).then(function (res) { finish(res || Response.error()); });
    });
    // On a slow connection, answer from cache after a few seconds rather
    // than leave a blank screen; the network copy still refreshes the cache.
    setTimeout(function () { fromCache(req).then(finish); }, NETWORK_TIMEOUT);
  });
}

function asset(e) {
  var req = e.request;
  return caches.match(req).then(function (hit) {
    return hit || fetch(req).then(function (res) {
      if (res.ok && res.type === "basic") {
        var copy = res.clone();
        e.waitUntil(caches.open(STATIC).then(function (c) { return c.put(req, copy); })
          .then(function () { return trim(STATIC, MAX_STATIC); }));
      }
      return res;
    });
  });
}

self.addEventListener("fetch", function (e) {
  var req = e.request;
  if (req.method !== "GET") return;
  var url = new URL(req.url);
  if (url.origin !== location.origin || url.pathname.indexOf("/api/") === 0) return;
  if (req.mode === "navigate") return e.respondWith(page(e));
  if (url.pathname.indexOf("/static/") === 0) return e.respondWith(asset(e));
});